                                    } else if merged.options.is_none() && other_methods.options.is_some() {
                                        if let method_routing::MethodEndpoint::BoxedHandler(handler) = other_methods.options {
                                            merged.options = method_routing::MethodEndpoint::BoxedHandler(handler);
                                        } else {
                                            merged.options = other_methods.options;
                                        }
                                    }

