                                        panic!(
                                            "Overlapping method route. Handler for `POST {path}` already exists"
                                        );
                                    } else if merged.post.is_none() && other_methods.post.is_some() {
                                        if let method_routing::MethodEndpoint::BoxedHandler(handler) = other_methods.post {
                                            merged.post = method_routing::MethodEndpoint::BoxedHandler(handler);
                                        } else {
                                            merged.post = other_methods.post;
                                        }
                                    }

                                    if merged.put.is_some() && other_methods.put.is_some() {
                                        panic!(
                                            "Overlapping method route. Handler for `PUT {path}` already exists"
                                        );
                                    } else if merged.put.is_none() && other_methods.put.is_some() {
                                        if let method_routing::MethodEndpoint::BoxedHandler(handler) = other_methods.put {
                                            merged.put = method_routing::MethodEndpoint::BoxedHandler(handler);
                                        } else {
                                            merged.put = other_methods.put;
                                        }
                                    }

