                                        if let method_routing::MethodEndpoint::BoxedHandler(handler) = other_methods.trace {
                                            merged.trace = method_routing::MethodEndpoint::BoxedHandler(handler);
                                        } else {
                                            merged.trace = other_methods.trace;
                                        }
                                    }

