                                    self.path_router.prev_route_id = RouteId(next_id);
                                    let id = self.path_router.prev_route_id;
                                    let mut node = Arc::try_unwrap(Arc::clone(&self.path_router.node))
                                        .unwrap_or_else(|shared| (*shared).clone());
                                    match node.insert(path, id) {
                                        Ok(()) => {
                                            self.path_router.node = Arc::new(node);
