        };

        self.catch_all_fallback = match (self.catch_all_fallback, catch_all_fallback) {
            (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
            (Fallback::Default(_), pick) | (pick, Fallback::Default(_)) => pick,
            _ => panic!("Cannot merge two `Router`s that both have a fallback"),
        };

